import {FISH} from './fish-config.js';import {fishPayment} from './fish-feed.js';
/** Toggle never creates credit, oxygen or a tick. @param {import('./engine.js').State} state @param {import('./fish-state.js').FishPond} pond @returns {string|undefined} */
export function toggleFishAir(state,pond){const g=state.fish;if(!g)return 'fishNotVisited';if(!pond.aeratorOn&&g.air.starter+g.air.recovery+pond.airPaidTicks===0&&state.coins<FISH.airCoins)return 'fishNoEnergy';pond.aeratorOn=!pond.aeratorOn;pond.serviceStatus='off';g.stats.aeratorToggles++;}
/** Shared finite credit first; paid runtime survives OFF/reload and cannot be refunded. @param {import('./engine.js').State} state @param {import('./fish-state.js').FishPond} pond @param {import('./fish-feed.js').FishTransaction} transact */
export function runFishAir(state,pond,transact){const g=state.fish;if(!g)return;if(!pond.aeratorOn){if(pond.serviceStatus!=='noCoins')pond.serviceStatus='off';return;}if(g.air.recovery){g.air.recovery--;g.stats.recoveryAirUsedTicks++;}else if(g.air.starter){g.air.starter--;g.stats.starterAirUsedTicks++;}else{if(!pond.airPaidTicks){if(state.coins<FISH.airCoins){pond.aeratorOn=false;pond.serviceStatus='noCoins';return;}const ticks=pond.efficient?FISH.efficientAirTicks:FISH.airTicks;fishPayment(state,'fish.energy',-FISH.airCoins,'energy.'+state.tick+'.'+pond.id,transact);pond.airPaidTicks+=ticks;g.stats.paidAirTicks+=ticks;}pond.airPaidTicks--;g.stats.airUsedTicks++;}const saturation=pond.volumeL*(state.weather==='hot'?7:8),incoming=Math.max(0,Math.min(900,saturation-pond.oxygenMg));pond.oxygenMg+=incoming;pond.balance.oxygenInMg+=incoming;pond.serviceStatus='running';}
